<?php declare(strict_types=1); ?>
<div class="actions"><div><span class="status">ADM · Financeiro</span><h1>Campanhas</h1><p class="meta">Cadastre descontos com prazo de validade para usar nas matrículas.</p></div><a class="button-primary" href="<?= $escape($basePath) ?>/admin/finance/campaigns/create"><i class="fa-solid fa-plus"></i> Nova campanha</a></div>
<?php if($message):?><p class="alert alert-success"><?= $escape($message) ?></p><?php endif;?><?php if($error):?><p class="alert alert-danger"><?= $escape($error) ?></p><?php endif;?><div class="table-responsive"><table><thead><tr><th>Campanha</th><th>Desconto</th><th>Validade</th><th>Situação</th><th>Ação</th></tr></thead><tbody><?php if($campaigns===[]):?><tr><td colspan="5">Nenhuma campanha cadastrada.</td></tr><?php endif;?><?php foreach($campaigns as$campaign):$expired=(string)$campaign['valid_until']<date('Y-m-d');?><tr><td><strong><?= $escape($campaign['name']) ?></strong></td><td><?= $escape(number_format((float)$campaign['discount_percent'],2,',','.')) ?>%</td><td><?= $escape(date('d/m/Y',strtotime((string)$campaign['valid_until']))) ?></td><td><span class="connection-badge"><?= (int)$campaign['is_active']!==1?'Inativa':($expired?'Expirada':'Ativa') ?></span></td><td><a class="button-icon" title="Editar campanha" href="<?= $escape($basePath) ?>/admin/finance/campaigns/<?= (int)$campaign['id'] ?>/edit"><i class="fa-solid fa-pen"></i></a></td></tr><?php endforeach;?></tbody></table></div>
